from src.base_conv import to_base, from_base


def test_to_base_binary():
    assert to_base(10, 2) == "1010"
    assert to_base(0, 2) == "0"
    assert to_base(255, 2) == "11111111"


def test_to_base_hex():
    assert to_base(255, 16) == "ff"
    assert to_base(26, 16) == "1a"
    assert to_base(0, 16) == "0"


def test_from_base_binary():
    assert from_base("1010", 2) == 10
    assert from_base("11111111", 2) == 255
    assert from_base("0", 2) == 0


def test_from_base_hex():
    assert from_base("ff", 16) == 255
    assert from_base("1a", 16) == 26


def test_roundtrip():
    for n in [0, 1, 42, 255, 1000]:
        for base in [2, 8, 16, 36]:
            assert from_base(to_base(n, base), base) == n
